// Generated by esquadro: do not edit. The command palette (Cmd+K or
// Ctrl+K): go to a page, find a record of any resource, create one, change
// the theme, sign out; all from the keyboard.
import { useQueries, useQueryClient } from "@tanstack/react-query"
import { useNavigate } from "@tanstack/react-router"
import { LogOut, Monitor, Moon, Plus, Search, Settings, Sun } from "lucide-react"
import { useTheme } from "next-themes"
import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button"
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
} from "@/components/ui/command"
import { Spinner } from "@/components/ui/spinner"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { isGroup, menu } from "@/menu.ts"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { signOut } from "./auth.tsx"
import { capitalize, t } from "./i18n.ts"
import type { Rec, ResourceMeta } from "./meta.ts"
import { SEARCH_DELAY } from "./search.tsx"

const OPEN = "esquadro:palette"

/** Opens the palette, from a button of yours. */
export function openPalette() {
  window.dispatchEvent(new Event(OPEN))
}

const mac = typeof navigator !== "undefined" && /Mac|iPhone|iPad/.test(navigator.platform)

/** The key that opens the palette, as this computer writes it. */
export const paletteKey = mac ? "⌘K" : "Ctrl K"

/** A button that opens the palette, for the header: its icon, the key on hover. */
export function PaletteButton() {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="size-10 rounded-full text-muted-foreground hover:text-foreground [&_svg]:size-5!"
          onClick={openPalette}
          aria-label={t("searchEverything")}
        >
          <Search />
        </Button>
      </TooltipTrigger>
      <TooltipContent>
        {t("searchEverything")} <kbd className="ml-1 font-mono">{paletteKey}</kbd>
      </TooltipContent>
    </Tooltip>
  )
}

export function CommandPalette() {
  const [open, setOpen] = useState(false)
  const [text, setText] = useState("")
  const [q, setQ] = useState("")
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const { setTheme } = useTheme()

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        setOpen((o) => !o)
      }
    }
    const onOpen = () => setOpen(true)
    document.addEventListener("keydown", onKey)
    window.addEventListener(OPEN, onOpen)
    return () => {
      document.removeEventListener("keydown", onKey)
      window.removeEventListener(OPEN, onOpen)
    }
  }, [])
  // After a pause in typing, the records are searched.
  useEffect(() => {
    const timer = setTimeout(() => setQ(text.trim()), SEARCH_DELAY)
    return () => clearTimeout(timer)
  }, [text])
  // Closed: it starts over next time.
  useEffect(() => {
    if (!open) {
      setText("")
      setQ("")
    }
  }, [open])

  const all = Object.values(resources as unknown as Record<string, ResourceMeta>)
  const searchable = all.filter((r) => !r.single && r.sorts.includes("relevance"))
  const found = useQueries({
    queries: searchable.map((r) => ({
      queryKey: [r.name, "palette", q],
      queryFn: ({ signal }) => r.api(api as never).list({ q, sort: "relevance", limit: 5, per_page: 5 }, { signal }),
      enabled: open && q.length >= 2,
      staleTime: 30_000,
    })),
  })
  const searching = found.some((f) => f.isFetching)

  const run = (action: () => unknown) => {
    setOpen(false)
    action()
  }
  const go = (to: string) => run(() => navigate({ to: to as never }))
  const pages = menu.main.flatMap((e) => (isGroup(e) ? e.items.map((i) => ({ ...i, group: e.label })) : [{ ...e, group: "" }]))

  return (
    <CommandDialog
      open={open}
      onOpenChange={setOpen}
      title={t("commandPalette")}
      description={t("paletteSearch")}
      showCloseButton={false}
      className="top-12 translate-y-0 rounded-2xl sm:max-w-lg [&_[cmdk-group-heading]]:pt-3 [&_[cmdk-group-heading]]:text-sm [&_[cmdk-group-heading]]:font-bold [&_[cmdk-group-heading]]:text-foreground [&_[cmdk-input-wrapper]]:h-14 [&_[cmdk-item]]:gap-3 [&_[cmdk-item]]:rounded-lg [&_[cmdk-item]]:py-2 [&_[cmdk-item]]:font-semibold [&_[cmdk-item]>svg:first-child]:box-content [&_[cmdk-item]>svg:first-child]:size-4! [&_[cmdk-item]>svg:first-child]:rounded-md [&_[cmdk-item]>svg:first-child]:border [&_[cmdk-item]>svg:first-child]:border-border [&_[cmdk-item]>svg:first-child]:p-1.5 [&_[cmdk-list]]:max-h-[min(60vh,420px)] [&_[cmdk-list]]:pb-2"
    >
      <CommandInput placeholder={t("paletteSearch")} value={text} onValueChange={setText}>
        <kbd className="pointer-events-none rounded-md border border-border px-1.5 py-0.5 text-[11px] font-semibold text-muted-foreground">Esc</kbd>
      </CommandInput>
      <CommandList>
        <CommandEmpty>{searching ? <Spinner className="mx-auto" /> : t("noResults", { q: text })}</CommandEmpty>
        {searchable.map((r, i) => {
          const items = found[i]?.data?.items ?? []
          if (q.length < 2 || items.length === 0) return null
          return (
            <CommandGroup key={r.name} heading={r.label}>
              {items.map((rec: Rec) => (
                <CommandItem key={rec.id} value={`${r.name}-${rec.id}`} keywords={[text]} onSelect={() => go(`/${r.name}/${rec.id}`)}>
                  <span className="truncate">{capitalize(String(rec[r.title] ?? rec.id))}</span>
                  <CommandShortcut>{capitalize(r.singular)}</CommandShortcut>
                </CommandItem>
              ))}
            </CommandGroup>
          )
        })}
        <CommandGroup heading={t("goTo")}>
          {pages.map((p) => (
            <CommandItem key={p.to} value={`${p.group} ${p.label}`} onSelect={() => go(p.to)}>
              {p.icon && <p.icon />}
              {p.label}
              {p.group && <CommandShortcut>{p.group}</CommandShortcut>}
            </CommandItem>
          ))}
        </CommandGroup>
        <CommandSeparator />
        <CommandGroup heading={t("create")}>
          {all.map((r) => (
            <CommandItem key={r.name} value={`${t("new")} ${r.singular}`} onSelect={() => go(`/${r.name}/new`)}>
              <Plus />
              {capitalize(t("creating", { name: r.singular }))}
            </CommandItem>
          ))}
        </CommandGroup>
        <CommandSeparator />
        <CommandGroup heading={t("theme")}>
          <CommandItem value={`${t("theme")} ${t("light")}`} onSelect={() => run(() => setTheme("light"))}>
            <Sun /> {t("light")}
          </CommandItem>
          <CommandItem value={`${t("theme")} ${t("dark")}`} onSelect={() => run(() => setTheme("dark"))}>
            <Moon /> {t("dark")}
          </CommandItem>
          <CommandItem value={`${t("theme")} ${t("system")}`} onSelect={() => run(() => setTheme("system"))}>
            <Monitor /> {t("system")}
          </CommandItem>
        </CommandGroup>
        <CommandSeparator />
        <CommandGroup heading={t("account")}>
          <CommandItem value={t("settings")} onSelect={() => run(() => navigate({ to: "/settings" as never }))}>
            <Settings /> {t("settings")}
          </CommandItem>
          <CommandItem
            value={t("signOut")}
            onSelect={() =>
              run(async () => {
                await signOut(queryClient)
                navigate({ to: "/login", search: { redirect: undefined } })
              })
            }
          >
            <LogOut /> {t("signOut")}
          </CommandItem>
        </CommandGroup>
      </CommandList>
    </CommandDialog>
  )
}
